window.PUBLICATIONS = {
  "profile": {"name": "Kuno Kurzhals", "title": "Dr.", "role": "Computer Science Researcher", "email": "kuno.kurzhals@visus.uni-stuttgart.de", "phone": "+49 711 685 88609", "address": "Allmandring 19, 70569 Stuttgart, Germany", "room": "00.107", "orcid": "https://orcid.org/0000-0003-4919-4582", "visus": "https://www.visus.uni-stuttgart.de/team/Kurzhals/", "bio": "I research visual analytics and eye tracking: developing visualizations of gaze data, evaluating how people interact with visualizations through user studies, and applying these methods in AR/VR, collaborative, and manufacturing settings. Current work focuses on multi-user eye tracking, LLMs as simulated users, and human-AI collaboration.", "interests": ["Eye Tracking", "Video Visualization", "Visual Analytics", "Evaluation Methods", "AR / VR", "User Studies"]}
  ,
  "publications": [
    {"id": 1, "year": 2026, "cat": "journal", "title": "Can LLMs Simulate Target Users in Visualization Case Studies?", "authors": ["Satkunarajan, J.", "Abdelaal, M.", "Koch, S.", "Kurzhals, K.", "Weiskopf, D."], "venue": "Computer Graphics Forum 45.3", "pages": "", "doi": "10.1111/cgf.70446", "detail": "Case studies are central to evaluating visualization research as they provide evidence for how the developed approaches support real users, real analytical work, and real data. Conducting such studies can be challenging, since target users with relevant domain expertise are often scarce or even entirely unavailable, while the visualization researchers may lack the required expertise to perform the evaluation themselves. Current research on Large Language Models (LLMs) has shown their strong reasoning ability and usefulness in domain‐specific downstream tasks, provoking the question: to what degree and with what capacity can LLMs fill the role of the target users in visualization case studies? We investigate this question by evaluating how LLMs can participate across different phases of visualization case studies. We propose a conceptual framework that explores the different levels of LLM involvement and potential roles when simulating target users. To sketch where the LLM substitution is most plausible, we embed our suggested integration of LLMs within the nested model for visualization theory and design. For evaluation, we replicate case studies from published and unpublished visualization research using multiple state‐of‐the‐art LLMs and compare the model‐generated insights to those reported in the papers. Our results show that LLMs can often generate plausible and sometimes even novel interpretations of visual patterns when used for result analysis and validation, but can also struggle when highly contextual, domain‐specific knowledge is required.", "image": "img/Can LLMs Simulate Target Users in Visualization Case Studies.png", "url": "https://diglib.eg.org/items/f8d1ba3c-e857-4b5e-808f-8cad01456957"},
    {"id": 2, "year": 2026, "cat": "conf", "title": "Social Interaction Graphs for Eye Tracking", "authors": ["Koch, M.", "Beck, S.", "Gutknecht, L.", "Hahn, B.", "Riedlinger, A.", "Schwendinger, I.", "Waimer, J.", "Burch, M.", "Koch, S.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–7", "doi": "10.1145/3797246.3805718", "detail": "Eye movements play an important role during social interaction, for instance, by indicating phases of mutual and joint attention. This type of gaze behavior has been researched extensively in pair collaboration but has been far less studied in the investigation of group activities. Further, the analysis of attention is often decoupled from speech, even though they are closely linked in social interactions. We introduce a visualization to facilitate joint analysis of gaze and speech among multiple participants during social activities. Our proposed social interaction graphs are two-layered arc diagrams that visualize pairwise relationships among participants. Our evaluation is based on two datasets of multiplayer tabletop gaming sessions recorded with five players. We present a traditional evaluation using eye-tracking metrics as a baseline and compare it with the additional findings possible with our approach.", "image": "img/Social Interaction Graphs for Eye Tracking.png"},
    {"id": 3, "year": 2026, "cat": "journal", "title": "A Multimodal Framework for Understanding Collaborative Design Processes", "authors": ["Koch, M.", "Pathmanathan, N.", "Weiskopf, D.", "Kurzhals, K."], "venue": "IEEE Transactions on Visualization and Computer Graphics 32.1", "pages": "582–592", "doi": "10.1109/tvcg.2025.3634232", "detail": "An essential task in analyzing collaborative design processes, such as those that are part of workshops in design studies, is identifying design outcomes and understanding how the collaboration between participants formed the results and led to decision-making. However, findings are typically restricted to a consolidated textual form based on notes from interviews or observations. A challenge arises from integrating different sources of observations, leading to large amounts and heterogeneity of collected data. To address this challenge we propose a practical, modular, and adaptable framework of workshop setup, multimodal data acquisition, AI-based artifact extraction, and visual analysis. Our interactive visual analysis system, reCAPit, allows the flexible combination of different modalities, including video, audio, notes, or gaze, to analyze and communicate important workshop findings. A multimodal streamgraph displays activity and attention in the working area, temporally aligned topic cards summarize participants' discussions, and drill-down techniques allow inspecting raw data of included sources. As part of our research, we conducted six workshops across different themes ranging from social science research on urban planning to a design study on band-practice visualization. The latter two are examined in detail and described as case studies. Further, we present considerations for planning workshops and challenges that we derive from our own experience and the interviews we conducted with workshop experts. Our research extends existing methodology of collaborative design workshops by promoting data-rich acquisition of multimodal observations, combined AI-based extraction and interactive visual analysis, and transparent dissemination of results.", "image": "img/A Multimodal Framework for Understanding Collaborative Design Processes.png"},
    {"id": 4, "image": "img/Exploring the Use of Augmented Reality for Multi-Human-Robot Collaboration with Industry Users in Timber Construction.png", "year": 2025, "cat": "conf", "title": "Exploring the Use of Augmented Reality for Multi-Human-Robot Collaboration with Industry Users in Timber Construction", "authors": ["Yang, X.", "Pathmanathan, N.", "Zabel, S.", "Amtsberg, F.", "Otto, S.", "Kurzhals, K.", "Sedlmair, M.", "Menges, A."], "venue": "Extended Abstracts of the CHI Conference on Human Factors in Computing Systems", "pages": "272:1–8", "doi": "10.1145/3706599.3720104", "detail": "As robots are introduced into construction environments, situations may arise where construction workers without programming expertise need to interact with robotic operations to ensure smooth and successful task execution. We designed a head-mounted augmented reality (AR) system that allowed control of the robot’s tasks and motions during human-robot collaboration (HRC) in timber assembly tasks. To explore workers’ feedback and attitudes towards HRC with this system, we conducted a user study with 10 carpenters. The workers collaborated in pairs with a heavy-payload industrial robot to construct a 2 x 3 m timber panel. The study contributes an evaluation of multi-human-robot collaboration along with qualitative feedback from the workers. Exploratory data analysis revealed the influence of asymmetrical user roles in multi-user collaborative construction, providing research directions for future work."},
    {"id": 5, "year": 2024, "cat": "journal", "title": "Visual Analysis of Fitness Landscapes in Architectural Design Optimization", "authors": ["Abdelaal, M.", "Galuschka, M.", "Zorn, M.", "Kannenberg, F.", "Menges, A.", "Wortmann, T.", "Weiskopf, D.", "Kurzhals, K."], "venue": "The Visual Computer 40.7", "pages": "4927–4940", "doi": "10.1007/s00371-024-03491-3", "detail": "In architectural design optimization, fitness landscapes are used to visualize design space parameters in relation to one or more objective functions for which they are being optimized. In our design study with domain experts, we developed a visual analytics framework for exploring and analyzing fitness landscapes spanning data, projection, and visualization layers. Within the data layer, we employ two surrogate models and three sampling strategies to efficiently generate a wide array of landscapes. On the projection layer, we use star coordinates and UMAP as two alternative methods for obtaining a 2D embedding of the design space. Our interactive user interface can visualize fitness landscapes as a continuous density map or a discrete glyph-based map. We investigate the influence of surrogate models and sampling strategies on the resulting fitness landscapes in a parameter study. Additionally, we present findings from a user study (N= 12), revealing how experts’ preferences regarding projection methods and visual representations may be influenced by their level of expertise, characteristics of the techniques, and the specific task at hand. Furthermore, we demonstrate the usability and usefulness of our framework by a case study from the architecture domain, involving one domain expert."},
    {"id": 6, "image": "img/ChoreoVis- Planning and AssessingFormations in Dance Choreographies.png", "year": 2024, "cat": "journal", "title": "ChoreoVis: Planning and Assessing Formations in Dance Choreographies", "authors": ["Beck, S.", "Doerr, N.", "Kurzhals, K.", "Riedlinger, A.", "Schmierer, F.", "Sedlmair, M.", "Koch, S."], "venue": "Computer Graphics Forum 43.3", "pages": "e15104:1–12", "doi": "10.1111/cgf.15104", "detail": "Sports visualization has developed into an active research field over the last decades. Many approaches focus on analyzing movement data recorded from unstructured situations, such as soccer. For the analysis of choreographed activities like formation dancing, however, the goal differs, as dancers follow specific formations in coordinated movement trajectories. To date, little work exists on how visual analytics methods can support such choreographed performances. To fill this gap, we introduce a new visual approach for planning and assessing dance choreographies. In terms of planning choreographies, we contribute a web application with interactive authoring tools and views for the dancers' positions and orientations, movement trajectories, poses, dance floor utilization, and movement distances. For assessing dancers' real‐world movement trajectories, extracted by manual bounding box annotations, we developed a timeline showing aggregated trajectory deviations and a dance floor view for detailed trajectory comparison. Our approach was developed and evaluated in collaboration with dance instructors, showing that introducing visual analytics into this domain promises improvements in training efficiency for the future."},
    {"id": 7, "year": 2024, "cat": "journal", "title": "Teaching Eye Tracking: Challenges and Perspectives", "authors": ["Burch, M.", "Kurzhals, K."], "venue": "Proceedings of the ACM on Human-Computer Interaction 8.ETRA", "pages": "237:1–17", "doi": "10.1145/3655611", "detail": "Eye tracking studies are more complicated to design, conduct, and to evaluate than traditional studies solely based on performance measures like error rates and response times. This is typically due to the more complex hardware setup, the calibration procedures, and the spatio-temporal nature of the recorded data that must be analyzed, visualized, or statistically evaluated. As a benefit, eye movement data contains patterns of visual attention over space and time that are not observable in standard error rates, completion times, and qualitative feedback. Students in the field of visualization, human-computer interaction, and user experience represent an interest group that would benefit from the application of eye tracking during their studies and in their future careers. Consequently, instructing them how to design, setup, conduct, and evaluate an eye tracking study is of special interest to current researchers involved in teaching. We describe education in eye tracking in five courses with 79 students from bachelor, master, and PhD levels. We outline our concept and discuss the challenges to raise people with no experience in eye tracking to a level of knowledge that allows them to apply this emerging technology to different scenarios including visual stimuli and related research questions. We discuss our teaching strategy in two course setups (summer school and traditional university lecture), the results of the students' eye tracking studies, and which challenges they and the teachers faced during the course."},
    {"id": 8, "year": 2024, "cat": "journal", "title": "Active Gaze Labeling: Visualization for Trust Building", "authors": ["Koch, M.", "Cao, N.", "Weiskopf, D.", "Kurzhals, K."], "venue": "IEEE Transactions on Visualization and Computer Graphics", "pages": "1–15", "doi": "10.1109/tvcg.2024.3392476", "detail": "Areas of interest (AOIs) are well-established means of providing semantic information for visualizing, analyzing, and classifying gaze data. However, the usual manual annotation of AOIs is time-consuming and further impaired by ambiguities in label assignments. To address these issues, we present an interactive labeling approach that combines visualization, machine learning, and user-centered explainable annotation. Our system provides uncertainty-aware visualization to build trust in classification with an increasing number of annotated examples. It combines specifically designed EyeFlower glyphs, dimensionality reduction, and selection and exploration techniques in an integrated workflow. The approach is versatile and hardware-agnostic, supporting video stimuli from stationary and unconstrained mobile eye tracking alike. We conducted an expert review to assess labeling strategies and trust building.", "image": "img/Active Gaze Labeling - Visualization for Trust Building.png"},
    {"id": 9, "image": "img/Anonymizing eye-tracking stimuli with stable diffusion.png", "year": 2024, "cat": "journal", "title": "Anonymizing Eye-Tracking Stimuli With Stable Diffusion", "authors": ["Kurzhals, K."], "venue": "Computers & Graphics 119", "pages": "103898:1–9", "doi": "10.1016/j.cag.2024.103898", "detail": "Casual users nowadays can create almost arbitrary image content by providing textual prompts to generative machine-learning models. These models rapidly improve image quality with each new generation, providing means to create photos, paintings in different styles, and even videos. One feature of such models is the ability to take an image as input and adjust content according to a prompt. A visual obfuscation of content can be achieved for static images and videos by slightly changing persons, text, and other objects. The potential of this technique can be applied in eye-tracking experiments for post-hoc dissemination of analysis results and visualization. In this work, we discuss how the technique could serve to anonymize stimuli (e.g., for double-blind reviews, remove product placements, etc.) and protect the privacy of people visible in the stimuli. We further investigate how the application of this anonymization process influences visual saliency and the depiction of stimuli in visualization techniques. Our results show that slight image transformations do not drastically change the saliency of a scene but obfuscate objects and faces while keeping important image structures for context."},
    {"id": 10, "year": 2024, "cat": "journal", "title": "Understanding Collaborative Learning of Molecular Structures in AR With Eye Tracking", "authors": ["Rau, T.", "Koch, M.", "Pathmanathan, N.", "Isenberg, T.", "Weiskopf, D.", "Sedlmair, M.", "Köhn, A.", "Kurzhals, K."], "venue": "IEEE Computer Graphics and Applications 44.6", "pages": "39–51", "doi": "10.1109/mcg.2024.3503903", "detail": "We present an approach for on-site instruction of multiple students accompanied by gaze-based monitoring to observe patterns of visual attention during task solving. We focus on collaborative processes in augmented reality (AR) that play an essential role in on-site and remote teaching alike. From a teaching perspective, it is important in such scenarios to communicate content and tasks effectively, observe whether students understand the task, and help appropriately. In our setting, students work with head-mounted displays with eye-tracking support to collaborate in a co-located space. The supervisor can observe the scene and the students and interact with them in a hybrid setup using both AR and a desktop PC. Attention monitoring and guidance are facilitated via a bidirectional mapping between 2D structural formulas and 3D molecules. We showcase our approach with an interactive teaching scenario in which chemistry students learn aspects of stereochemistry by interacting with virtual 3D models of molecular structures. An interview with supervisors and students showed that our approach has much potential in classroom applications for (1) engaging students in collaborative task solving and (2) assisting teachers in monitoring and supporting the learning processes of their students."},
    {"id": 11, "image": "img/Eye Tracking on Text Reading with Visual Enhancements.png", "year": 2024, "cat": "conf", "title": "Eye Tracking on Text Reading with Visual Enhancements", "authors": ["Huth, F.", "Koch, M.", "Awad-Mohammed, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "80:1–7", "doi": "10.1145/3649902.3653521", "detail": "The interplay between text and visualization is gaining importance for media where traditional text is enriched by visual elements to improve readability and emphasize facts. In two controlled eye-tracking experiments (N = 12), we approach answers to the question: How do visualization techniques influence reading behavior? We compare plain text to that marked with highlights, icons, and word-sized data visualizations. We assess quantitative metrics (eye movement, completion time, error rate) and subjective feedback (personal preference and ratings). The results indicate that visualization techniques, especially in the first experiment, show promising trends for improved reading behavior. The results also show the need for further research to make reading more effective and inform suggestions for future studies."},
    {"id": 12, "year": 2024, "cat": "conf", "title": "NMF-Based Analysis of Mobile Eye-Tracking Data", "authors": ["Klötzl, D.", "Krake, T.", "Heyen, F.", "Becher, M.", "Koch, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "76:1–9", "doi": "10.1145/3649902.3653518", "detail": "The depiction of scanpaths from mobile eye-tracking recordings by thumbnails from the stimulus allows the application of visual computing to detect areas of interest in an unsupervised way. We suggest using nonnegative matrix factorization (NMF) to identify such areas in stimuli. For a user-defined integer k, NMF produces an explainable decomposition into k components, each consisting of a spatial representation associated with a temporal indicator. In the context of multiple eye-tracking recordings, this leads to k spatial representations, where the temporal indicator highlights the appearance within recordings. The choice of k provides an opportunity to control the refinement of the decomposition, i.e., the number of areas to detect. We combine our NMF-based approach with visualization techniques to enable an exploratory analysis of multiple recordings. Finally, we demonstrate the usefulness of our approach with mobile eye-tracking data of an art gallery."},
    {"id": 13, "image": "img/How Deep Is Your Gaze.png", "year": 2024, "cat": "conf", "title": "How Deep Is Your Gaze? Leveraging Distance in Image-Based Gaze Analysis", "authors": ["Koch, M.", "Pathmanathan, N.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–7", "doi": "10.1145/3649902.3653349", "detail": "Image thumbnails are a valuable data source for fixation filtering, scanpath classification, and visualization of eye tracking data. They are typically extracted with a constant size, approximating the foveated area. As a consequence, the focused area of interest in the scene becomes less prominent in the thumbnail with increasing distance, affecting image-based analysis techniques. In this work, we propose depth-adaptive thumbnails, a method for varying image size according to the eye-to-object distance. Adjusting the visual angle relative to the distance leads to a zoom effect on the focused area. We evaluate our approach on recordings in augmented reality, investigating the similarity of thumbnails and scanpaths. Our quantitative findings suggest that considering the eye-to-object distance improves the quality of data analysis and visualization. We demonstrate the utility of depth-adaptive thumbnails for applications in scanpath comparison and visualization."},
    {"id": 14, "year": 2024, "cat": "conf", "title": "Testing the Test: Observations When Assessing Visualization Literacy of Domain Experts", "authors": ["Öney, S.", "Abdelaal, M.", "Kurzhals, K.", "Betz, P.", "Kropp, C.", "Weiskopf, D."], "venue": "IEEE BELIV – Evaluation and Beyond: Methodological Approaches for Visualization", "pages": "106–114", "doi": "10.1109/beliv64461.2024.00017", "detail": "Various standardized tests exist that assess individuals' visualization literacy. Their use can help to draw conclusions from studies. However, it is not taken into account that the test itself can create a pressure situation where participants might fear being exposed and assessed negatively. This is especially problematic when testing domain experts in design studies. We conducted interviews with experts from different domains performing the Mini-VLAT test for visualization literacy to identify potential problems. Our participants reported that the time limit per question, ambiguities in the questions and visualizations, and missing steps in the test procedure mainly had an impact on their performance and content. We discuss possible changes to the test design to address these issues and how such assessment methods could be integrated into existing evaluation procedures."},
    {"id": 15, "image": "img/Investigating the Gap.png", "year": 2024, "cat": "conf", "title": "Investigating the Gap: Gaze and Movement Analysis in Immersive Environments", "authors": ["Pathmanathan, N.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "75:1–7", "doi": "10.1145/3649902.3653522", "detail": "Behavioral data comprising movement and gaze data is an important source to understand how people perceive and interact with their environment. In the past, visual analysis of such data mainly focused on desktop applications. With the improvements in visualization for virtual and augmented reality, new evaluation scenarios come up that also require new analysis approaches. Especially techniques for the analysis of immersive environments are rare. This work provides an overview of existing work presenting visualizations of such data in desktop-based virtual environments and in an immersive context. There is a need for more research on visualizing gaze and movement in immersive environments. We discuss the advantages and disadvantages of desktop-based against immersive visualizations and provide an outlook for future research directions."},
    {"id": 16, "image": "img/Eyes on the Task- Gaze Analysis of Situated Visualization.png", "year": 2024, "cat": "conf", "title": "Eyes on the Task: Gaze Analysis of Situated Visualization for Collaborative Tasks", "authors": ["Pathmanathan, N.", "Rau, T.", "Yang, X.", "Calepso, A. S.", "Amtsberg, F.", "Menges, A.", "Sedlmair, M.", "Kurzhals, K."], "venue": "IEEE Conference on Virtual Reality and 3D User Interfaces (VR)", "pages": "785–795", "doi": "10.1109/vr58804.2024.00098", "detail": "The use of augmented reality technology to support humans with situated visualization in complex tasks such as navigation or assembly has gained increasing importance in research and industrial applications. One important line of research regards supporting and understanding collaborative tasks. Analyzing collaboration patterns is usually done by conducting observations and interviews. To expand these methods, we argue that eye tracking can be used to extract further insights and quantify behavior. To this end, we contribute a study that uses eye tracking to investigate participant strategies for solving collaborative sorting and assembly tasks. We compare participants’ visual attention during situated instructions in AR and traditional paper-based instructions as a baseline. By investigating the performance and gaze behavior of the participants, different strategies for solving the provided tasks are revealed. Our results show that with situated visualization, participants focus more on task-relevant areas and require less discussion between collaboration partners to solve the task at hand."},
    {"id": 17, "year": 2023, "cat": "journal", "title": "Visual Gaze Labeling for Augmented Reality Studies", "authors": ["Öney, S.", "Pathmanathan, N.", "Becher, M.", "Sedlmair, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "Computer Graphics Forum 42.3", "pages": "373–384", "doi": "10.1111/cgf.14837", "detail": "Augmented Reality (AR) provides new ways for situated visualization and human‐computer interaction in physical environments. Current evaluation procedures for AR applications rely primarily on questionnaires and interviews, providing qualitative means to assess usability and task solution strategies. Eye tracking extends these existing evaluation methodologies by providing indicators for visual attention to virtual and real elements in the environment. However, the analysis of viewing behavior, especially the comparison of multiple participants, is difficult to achieve in AR. Specifically, the definition of areas of interest (AOIs), which is often a prerequisite for such analysis, is cumbersome and tedious with existing approaches. To address this issue, we present a new visualization approach to define AOIs, label fixations, and investigate the resulting annotated scanpaths. Our approach utilizes automatic annotation of gaze on virtual objects and an image‐based approach that also considers spatial context for the manual annotation of objects in the real world. Our results show, that with our approach, eye tracking data from AR scenes can be annotated and analyzed flexibly with respect to data aspects and annotation strategies."},
    {"id": 18, "year": 2023, "cat": "journal", "title": "Been There, Seen That: Visualization of Movement and 3D Eye Tracking Data from Real-World Environments", "authors": ["Pathmanathan, N.", "Öney, S.", "Becher, M.", "Sedlmair, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "Computer Graphics Forum 42.3", "pages": "385–396", "doi": "10.1111/cgf.14838", "detail": "The distribution of visual attention can be evaluated using eye tracking, providing valuable insights into usability issues and interaction patterns. However, when used in real, augmented, and collaborative environments, new challenges arise that go beyond desktop scenarios and purely virtual environments. Toward addressing these challenges, we present a visualization technique that provides complementary views on the movement and eye tracking data recorded from multiple people in real‐world environments. Our method is based on a space‐time cube visualization and a linked 3D replay of recorded data. We showcase our approach with an experiment that examines how people investigate an artwork collection. The visualization provides insights into how people moved and inspected individual pictures in their spatial context over time. In contrast to existing methods, this analysis is possible for multiple participants without extensive annotation of areas of interest. Our technique was evaluated with a think‐aloud experiment to investigate analysis strategies and an interview with domain experts to examine the applicability in other research fields."},
    {"id": 19, "year": 2023, "cat": "conf", "title": "Reading Strategies for Graph Visualizations that Wrap Around in Torus Topology", "authors": ["Chen, K.", "Ngo, Q. Q.", "Kurzhals, K.", "Marriott, K.", "Dwyer, T.", "Sedlmair, M.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "67:1–7", "doi": "10.1145/3588015.3589841", "detail": "We investigate reading strategies for node-link diagrams that wrap around the boundaries in a flattened torus topology by examining eye tracking data recorded in a previous controlled study. Prior work showed that torus drawing affords greater flexibility in clutter reduction than traditional node-link representations, but impedes link-and-path exploration tasks, while repeating tiles around boundaries aids comprehension. However, it remains unclear what strategies users apply in different wrapping settings. This is important for design implications for future work on more effective wrapped visualizations for network applications, and cyclic data that could benefit from wrapping. We perform visual-exploratory data analysis of gaze data, and conduct statistical tests derived from the patterns identified. Results show distinguishable gaze behaviors, with more visual glances and transitions between areas of interest in the non-replicated layout. Full-context has more successful visual searches than partial-context, but the gaze allocation indicates that the layout could be more space-efficient."},
    {"id": 20, "year": 2023, "cat": "conf", "title": "Privacy in Eye Tracking Research with Stable Diffusion", "authors": ["Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "70:1–7", "doi": "10.1145/3588015.3589842", "detail": "Image-generative models take textual prompts as input and generate almost arbitrary image content based on the underlying training data. This technology is rapidly developing and produces better results with each new generation of trained models. Apart from the application to create artwork, we see potential in deploying such models for eye-tracking research with respect to anonymizing content in visual stimuli. One feature of such models is the ability to take an image as input and adjust content according to a prompt. Hence, privacy-preserving visualization of stimuli can be achieved for static images and videos by slightly adjusting content to anonymize persons, text, and other sensible sources. In this work, we will discuss how this process can be applied to the presentation and dissemination of results with respect to privacy issues resulting from eye-tracking experiments."},
    {"id": 21, "year": 2023, "cat": "chapter", "title": "Visualization Psychology for Eye Tracking Evaluation", "authors": ["Koch, M.", "Kurzhals, K.", "Burch, M.", "Weiskopf, D."], "venue": "in: Visualization Psychology (Eds. Szafir, Borgo, Chen, Edwards, Fisher, Padilla), Springer, Cham", "pages": "243–260", "doi": "10.1007/978-3-031-34738-2_10", "detail": "Technical progress in hardware and software enables us to record gaze data in everyday situations and over long time spans. Among a multitude of research opportunities, this technology enables visualization researchers to catch a glimpse behind performance measures and into the perceptual and cognitive processes of people using visualization techniques. The majority of eye tracking studies performed for visualization research is limited to the analysis of gaze distributions and aggregated statistics, thus only covering a small portion of insights that can be derived from gaze data. We argue that incorporating theories and methodology from psychology and cognitive science will benefit the design and evaluation of eye tracking experiments for visualization. This book chapter provides an overview of how eye tracking can be used in a variety of study designs. Further, we discuss the potential merits of cognitive models for the evaluation of visualizations. We exemplify these concepts on two scenarios, each focusing on a different eye tracking study. Lastly, we identify several call for actions."},
    {"id": 22, "year": 2022, "cat": "journal", "title": "Comparative Evaluation of Bipartite, Node-Link, and Matrix-Based Network Representations", "authors": ["Abdelaal, M.", "Schiele, N. D.", "Angerbauer, K.", "Kurzhals, K.", "Sedlmair, M.", "Weiskopf, D."], "venue": "IEEE Transactions on Visualization and Computer Graphics 29.1", "pages": "896–906", "doi": "10.1109/tvcg.2022.3209427", "detail": "This work investigates and compares the performance of node-link diagrams, adjacency matrices, and bipartite layouts for visualizing networks. In a crowd-sourced user study ( n=150), we measure the task accuracy and completion time of the three representations for different network classes and properties. In contrast to the literature, which covers mostly topology-based tasks (e.g., path finding) in small datasets, we mainly focus on overview tasks for large and directed networks. We consider three overview tasks on networks with 500 nodes: (T1) network class identification, (T2) cluster detection, and (T3) network density estimation, and two detailed tasks: (T4) node in-degree vs. out-degree and (T5) representation mapping, on networks with 50 and 20 nodes, respectively. Our results show that bipartite layouts are beneficial for revealing the overall network structure, while adjacency matrices are most reliable across the different tasks.", "video": "https://www.youtube.com/watch?v=h3tABLN5WXs"},
    {"id": 23, "year": 2022, "cat": "journal", "title": "Situated Visual Analysis and Live Monitoring for Manufacturing", "authors": ["Becher, M.", "Herr, D.", "Muller, C.", "Kurzhals, K.", "Reina, G.", "Wagner, L.", "Ertl, T.", "Weiskopf, D."], "venue": "IEEE Computer Graphics and Applications 42.2", "pages": "33–44", "doi": "10.1109/mcg.2022.3157961", "detail": "Modern machines continuously log status reports over long periods of time, which are valuable data to optimize working routines. Data visualization is a commonly used tool to gain insights into these data, mostly in retrospective (e.g., to determine causal dependencies between the faults of different machines). We present an approach to bring such visual analyses to the shop floor to support reacting to faults in real time. This approach combines spatio-temporal analyses of time series using a handheld touch device with augmented reality for live monitoring. Important information augments machines directly in their real-world context, and detailed logs of current and historical events are displayed on the handheld device. In collaboration with an industry partner, we designed and tested our approach on a live production line to obtain feedback from operators. We compare our approach for monitoring and analysis with existing solutions that are currently deployed."},
    {"id": 24, "image": "img/A Spiral into the Mind.png", "year": 2022, "cat": "journal", "title": "A Spiral into the Mind: Gaze Spiral Visualization for Mobile Eye Tracking", "authors": ["Koch, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "Proceedings of the ACM on Computer Graphics and Interactive Techniques 5.2", "pages": "20:1–16", "doi": "10.1145/3530795", "detail": "Comparing mobile eye tracking data from multiple participants without information about areas of interest (AOIs) is challenging because of individual timing and coordinate systems. We present a technique, the gaze spiral, that visualizes individual recordings based on image content of the stimulus. The spiral layout of the slitscan visualization is used to create a compact representation of scanpaths. The visualization provides an overview of multiple recordings even for long time spans and helps identify and annotate recurring patterns within recordings. The gaze spirals can also serve as glyphs that can be projected to 2D space based on established scanpath metrics in order to interpret the metrics and identify groups of similar viewing behavior. We present examples based on two egocentric datasets to demonstrate the effectiveness of our approach for annotation and comparison tasks. Our examples show that the technique has the potential to let users compare even long-term recordings of pervasive scenarios without manual annotation."},
    {"id": 25, "year": 2022, "cat": "conf", "title": "Evaluating Situated Visualization in AR with Eye Tracking", "authors": ["Kurzhals, K.", "Becher, M.", "Pathmanathan, N.", "Reina, G."], "venue": "IEEE BELIV – Evaluation and Beyond: Methodological Approaches for Visualization", "pages": "77–84", "doi": "10.1109/beliv57783.2022.00013", "detail": "Augmented reality (AR) technology provides means for embedding visualization in a real-world context. Such techniques allow situated analyses of live data in their spatial domain. However, as existing techniques have to be adapted for this context and new approaches will be developed, the evaluation thereof poses new challenges for researchers. Apart from established performance measures, eye tracking has proven to be a valuable means to assess visualizations qualitatively and quantitatively. We discuss the challenges and opportunities of eye tracking for the evaluation of situated visualizations. We envision that an extension of gaze-based evaluation methodology into this field will provide new insights on how people perceive and interact with visualizations in augmented reality.", "video": "https://www.youtube.com/watch?v=wncZd4xxqdk"},
    {"id": 26, "year": 2021, "cat": "journal", "title": "Visual Analysis of Spatio-temporal Phenomena with 1D Projections", "authors": ["Franke, M.", "Martin, H.", "Koch, S.", "Kurzhals, K."], "venue": "Computer Graphics Forum 40.3", "pages": "335–347", "doi": "10.1111/cgf.14311", "detail": "It is crucial to visually extrapolate the characteristics of their evolution to understand critical spatio‐temporal events such as earthquakes, fires, or the spreading of a disease. Animations embedded in the spatial context can be helpful for understanding details, but have proven to be less effective for overview and comparison tasks. We present an interactive approach for the exploration of spatio‐temporal data, based on a set of neighborhood‐preserving 1D projections which help identify patterns and support the comparison of numerous time steps and multivariate data. An important objective of the proposed approach is the visual description of local neighborhoods in the 1D projection to reveal patterns of similarity and propagation. As this locality cannot generally be guaranteed, we provide a selection of different projection techniques, as well as a hierarchical approach, to support the analysis of different data characteristics. In addition, we offer an interactive exploration technique to reorganize and improve the mapping locally to users' foci of interest. We demonstrate the usefulness of our approach with different real‐world application scenarios and discuss the feedback we received from domain and visualization experts."},
    {"id": 27, "year": 2021, "cat": "conf", "title": "Image-Based Projection Labeling for Mobile Eye Tracking", "authors": ["Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "4:1–12", "doi": "10.1145/3448017.3457382", "detail": "The annotation of gaze data concerning investigated areas of interest (AOIs) poses a time-consuming step in the analysis procedure of eye tracking experiments. For data from mobile eye tracking glasses, the annotation effort is further increased because each recording has to be investigated individually. Automated approaches based on supervised machine learning require pre-trained categories which are hard to obtain without human interpretation, i.e., labeling ground truth data. We present an interactive visualization approach that supports efficient annotation of gaze data based on image content participants with eye tracking glasses focused on. Recordings can be segmented individually to reduce the annotation effort. Thumbnails represent segments visually and are projected on a 2D plane for a fast comparison of AOIs. Annotated scanpaths can then be interpreted directly with the timeline visualization. We showcase our approach with three different scenarios.", "video": "https://www.youtube.com/watch?v=rWp6mpu0Xk8"},
    {"id": 28, "year": 2020, "cat": "conf", "title": "AnnoXplorer: A Scalable, Integrated Approach for the Visual Analysis of Text Annotations", "authors": ["Baumann, M.", "Minasyan, H.", "Koch, S.", "Kurzhals, K.", "Ertl, T."], "venue": "15th International Joint Conference on Computer Vision, Imaging and Computer Graphics Theory and Applications (VISIGRAPP)", "pages": "62–75", "doi": "10.5220/0008965400620075", "detail": "Text annotation data in terms of a series of tagged text segments can pose scalability challenges within the dimensions of quantity (long texts bearing many annotations), configuration (overlapping annotations or annotations with multiple tags), or source (annotations by multiple annotators). Accordingly, exploration tasks such as navigating within a long annotated text, recognizing patterns in the annotation data or assessing differences between annotators can be demanding. Our approach of an annotation browser deals with all of these data and task challenges simultaneously by providing a continuous range of views on large amounts of complex annotation data from multiple sources. We achieve this by using a combined geometric/semantic zooming mechanism that operates on an abstract representation of the sequence of a text’s tokens and the annotations thereupon, which is interlinked with a view on the text itself. The approach was developed in the context of a joint project with researchers from fields concerned with textual sources. We derive our approach’s requirements from a series of tasks that are typical in natural language processing and digital humanities, show how it supports these tasks, and discuss it in the light of the feedback we got from our domain experts.", "image": "img/annoxplorer-a-scalable-integrated-approach-for-the-visual-analysis-of-text-annotations.png"},
    {"id": 29, "year": 2020, "cat": "conf", "title": "Visual Analysis of Eye Movements During Game Play", "authors": ["Burch, M.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "59:1–5", "doi": "10.1145/3379156.3391839", "detail": "Eye movements indicate visual attention and strategies during game play, regardless of whether in board, sports, or computer games. Additional factors such as individual vs. group play and active playing vs. observing game play further differentiate application scenarios for eye movement analysis. Visual analysis has proven to be an effective means to investigate and interpret such highly dynamic spatio-temporal data. In this paper, we contribute a classification strategy for different scenarios for the visual analysis of gaze data during game play. Based on an initial sample of related work, we derive multiple aspects comprising data sources, game mode, player number, player state, analysis mode, and analysis goal. We apply this classification strategy to describe typical analysis scenarios and research questions as they can be found in related work. We further discuss open challenges and research directions for new application scenarios of eye movements in game play.", "image": "img/visual-analysis-of-eye-movements-during-game-play.png"},
    {"id": 30, "year": 2020, "cat": "conf", "title": "Gaze-Aware Mixed-Reality: Addressing Privacy Issues With Eye Tracking", "authors": ["Göbel, F.", "Kurzhals, K.", "Raubal, M.", "Schinazi, V. R."], "venue": "Workshop on Exploring Potentially Abusive Ethical, Social and Political Implications of Mixed Reality in HCI", "pages": "1–7", "doi": "10.3929/ETHZ-B-000409514", "detail": "Current Mixed Reality (MR) systems rely on a variety of sensors (e.g., cameras, eye tracking, GPS) to create immersive experiences.Data collected by these sensors are necessary to generate detailed models of a user and the environment that allow for different interactions with the virtual and the real world.Generally, these data contain sensitive information about the user, objects, and other people that make up the interaction.This is particularly the case for MR systems with eye tracking, because these devices are capable of inferring the identity and cognitive processes related to attention and arousal of a user.The goal of this position paper is to raise awareness on privacy issues that result from aggregating user data from multiple sensors in MR.Specifically, we focus on the challenges that arise from collecting eye tracking data and outline different ways gaze data may contribute to alleviate some of the privacy concerns from aggregating sensor data."},
    {"id": 31, "year": 2020, "cat": "conf", "title": "Gaze-Adaptive Lenses for Feature-Rich Information Spaces", "authors": ["Göbel, F.", "Kurzhals, K.", "Schinazi, V. R.", "Kiefer, P.", "Raubal, M."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "15:1–8", "doi": "10.1145/3379155.3391323", "detail": "The inspection of feature-rich information spaces often requires supportive tools that reduce visual clutter without sacrificing details. One common approach is to use focus+context lenses that provide multiple views of the data. While these lenses present local details together with global context, they require additional manual interaction. In this paper, we discuss the design space for gaze-adaptive lenses and present an approach that automatically displays additional details with respect to visual focus. We developed a prototype for a map application capable of displaying names and star-ratings of different restaurants. In a pilot study, we compared the gaze-adaptive lens to a mouse-only system in terms of efficiency, effectiveness, and usability. Our results revealed that participants were faster in locating the restaurants and more accurate in a map drawing task when using the gaze-adaptive lens. We discuss these results in relation to observed search strategies and inspected map areas.", "image": "img/gaze-adaptive-lenses-for-feature-rich-information-spaces.png"},
    {"id": 32, "year": 2020, "cat": "conf", "title": "Visual Analysis for Spatio-Temporal Event Correlation in Manufacturing", "authors": ["Herr, D.", "Kurzhals, K.", "Ertl, T."], "venue": "53rd Hawaii International Conference on System Sciences (HICSS)", "pages": "1330–1339", "doi": "10.24251/hicss.2020.164", "detail": "The analysis of events with spatio-temporal context and their interdependencies is a crucial task in the manufacturing domain. In general, understanding this context, for example investigating error messages or alerts is important to take corrective actions. In the manufacturing domain, comprehending the relations of errors is often based on the technicians’ experience. Validation of cause-effect relations is necessary to understand if an effect has a preceding causality, eg, if an error is the result of multiple issues from previous working steps. We present an approach to investigate spatio-temporal relations between such events. Based on a time-sensitive correlation measure, we provide multiple coordinated views to analyze and filter the data. In collaboration with an industry partner, we developed a visual analytics approach for error logs reported by machines that covers a multitude of analysis tasks. We present a case study based on real-world event logs of an assembly line with feedback from our industry partner’s domain experts. Furthermore, we discuss how our approach is applicable in other domains.", "image": "img/visual-analysis-for-spatio-temporal-event-correlation-in-manufacturing.png"},
    {"id": 33, "year": 2020, "cat": "conf", "title": "A View on the Viewer: Gaze-Adaptive Captions for Videos", "authors": ["Kurzhals, K.", "Göbel, F.", "Angerbauer, K.", "Sedlmair, M.", "Raubal, M."], "venue": "CHI Conference on Human Factors in Computing Systems", "pages": "139:1–12", "doi": "10.1145/3313831.3376266", "detail": "Subtitles play a crucial role in cross-lingual distribution of multimedia content and help communicate information where auditory content is not feasible (loud environments, hearing impairments, unknown languages). Established methods utilize text at the bottom of the screen, which may distract from the video. Alternative techniques place captions closer to related content (e.g., faces) but are not applicable to arbitrary videos such as documentations. Hence, we propose to leverage live gaze as indirect input method to adapt captions to individual viewing behavior. We implemented two gaze-adaptive methods and compared them in a user study (n=54) to traditional captions and audio-only videos. The results show that viewers with less experience with captions prefer our gaze-adaptive methods as they assist them in reading. Furthermore, gaze distributions resulting from our methods are closer to natural viewing behavior compared to the traditional approach. Based on these results, we provide design implications for gaze-adaptive captions.", "image": "img/a-view-on-the-viewer-gaze-adaptive-captions-for-videos.png", "video": "https://www.youtube.com/watch?v=L9SwDEgQBpY"},
    {"id": 34, "year": 2020, "cat": "conf", "title": "Visual Analytics and Annotation of Pervasive Eye Tracking Video", "authors": ["Kurzhals, K.", "Rodrigues, N.", "Koch, M.", "Stoll, M.", "Bruhn, A.", "Bulling, A.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "16:1–9", "doi": "10.1145/3379155.3391326", "detail": "We propose a new technique for visual analytics and annotation of long-term pervasive eye tracking data for which a combined analysis of gaze and egocentric video is necessary. Our approach enables two important tasks for such data for hour-long videos from individual participants: (1) efficient annotation and (2) direct interpretation of the results. Exemplary time spans can be selected by the user and are then used as a query that initiates a fuzzy search of similar time spans based on gaze and video features. In an iterative refinement loop, the query interface then provides suggestions for the importance of individual features to improve the search results. A multi-layered timeline visualization shows an overview of annotated time spans. We demonstrate the efficiency of our approach for analyzing activities in about seven hours of video in a case study and discuss feedback on our approach from novices and experts performing the annotation task.", "image": "img/visual-analytics-and-annotation-of-pervasive-eye-tracking-video.png", "video": "https://www.youtube.com/watch?v=UVDsgj-MjDU"},
    {"id": 35, "year": 2019, "cat": "conf", "title": "Space-Time Volume Visualization of Gaze and Stimulus", "authors": ["Bruder, V.", "Kurzhals, K.", "Frey, S.", "Weiskopf, D.", "Ertl, T."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "12:1–9", "doi": "10.1145/3314111.3319812", "detail": "We present a method for the spatio-temporal analysis of gaze data from multiple participants in the context of a video stimulus. For such data, an overview of the recorded patterns is important to identify common viewing behavior (such as attentional synchrony) and outliers. We adopt the approach of space-time cube visualization, which extends the spatial dimensions of the stimulus by time as the third dimension. Previous work mainly handled eye tracking data in the space-time cube as point cloud, providing no information about the stimulus context. This paper presents a novel visualization technique that combines gaze data, a dynamic stimulus, and optical flow with volume rendering to derive an overview of the data with contextual information. With specifically designed transfer functions, we emphasize different data aspects, making the visualization suitable for explorative analysis and for illustrative support of statistical findings alike.", "image": "img/space-time-volume-visualization-of-gaze-and-stimulus.png"},
    {"id": 36, "year": 2019, "cat": "conf", "title": "Visual Exploration of Topics in Multimedia News Corpora", "authors": ["John, M.", "Kurzhals, K.", "Ertl, T."], "venue": "23rd International Conference on Information Visualisation (INFOVIS)", "pages": "241–248", "doi": "10.1109/iv.2019.00048", "detail": "The increasing availability of digital multimedia content has led to the need of new approaches for the analysis of large databases containing video and associated data, for example, subtitles. Visualization provides valuable insights of such dataset, complementing approaches solely based on techniques for knowledge discovery in databases and information retrieval. Hence, visual analytics, combining automatic processing with interactive data visualization, has proven to be an effective means to explore and interpret such data. The analysis of news corpora represents a typical task for such a scenario. Domain experts such as journalists and social science scholars require an overview of important topics, the temporal coherence of events, and they should be able to compare different topics. We present a visual analytics approach that aims to support these tasks with automatic video preprocessing, topic extraction, clustering, and dimensionality reduction. Coordinated linked views support the flexible inspection of the dataset and the processed results. We further discuss the application of our approach in a usage scenario, inspecting the dataset of a daily news broadcast of the year 2015.", "image": "img/visual-exploration-of-topics-in-multimedia-news-corpora.png"},
    {"id": 37, "year": 2019, "cat": "conf", "title": "Towards Seamless Mobile Learning with Mixed Reality on Head-Mounted Displays", "authors": ["Sailer, C.", "Rudi, D.", "Kurzhals, K.", "Raubal, M."], "venue": "World Conference on Mobile and Contextual Learning (WCW-MCL)", "pages": "69–76", "doi": "10.3929/ETHZ-B-000365881", "detail": "This paper discusses the opportunities and challenges of utilizing optical (head-mounted) displays for mixed reality in the context of seamless mobile learning. Recent technological developments have significantly improved the capabilities and the mobility of head-mounted displays. Future displays, frequently referred to as data glasses, will be even more lightweight, have a larger naturally sized field of view, and will redefine the standing of mixed reality in economy and society. We envision that these immersive displays will introduce a new world of didactical opportunities and novel context-aware designs for seamless mobile learning, particularly in outdoor learning environments. Our discussion is based on an extensive literature review and first-hand experience with applying this type of novel technology in learning scenarios. Our considerations comprise new ways of collaborative learning and communication between peers, the role of human-computer interaction, the visualization of learning content, and exemplary learning scenarios with mixed reality. We further provide an overview of potential research directions to be pursued in the near future.", "image": "img/towards-seamless-mobile-learning-with-mixed-reality-on-head-mounted-displays.png"},
    {"id": 38, "year": 2018, "cat": "journal", "title": "Exploring the Visualization Design Space with Repertory Grids", "authors": ["Kurzhals, K.", "Weiskopf, D."], "venue": "Computer Graphics Forum 37.3", "pages": "133–144", "doi": "10.1111/cgf.13407", "detail": "There is an ongoing discussion in the visualization community about the relevant factors that render a visualization effective, expressive, memorable, aesthetically pleasing, etc. These factors lead to a large design space for visualizations. To explore this design space, qualitative research methods based on observations and interviews are often necessary. We describe an interview method that allows us to systematically acquire and assess important factors from subjective answers by interviewees. To this end, we adopt the repertory grid methodology in the context of visualization. It is based on the personal construct theory: each personality interprets a topic based on a set of personal, basic constructs expressed as contrasts. For the individual interpretation of visualizations, this means that these personal terms can be very different, depending on numerous influences, such as the prior experiences of the interviewed person. We present an interviewing process, visual interface, and qualitative and quantitative analysis procedures that are specifically devised to fit the needs of visualization applications. A showcase interview with 15 typical static information visualizations and 10 participants demonstrates that our approach is effective in identifying common constructs as well as individual differences. In particular, we investigate differences between expert and nonexpert interviewees. Finally, we discuss the differences to other qualitative methods and how the repertory grid can be embedded in existing theoretical frameworks of visualization research for the design process.", "image": "img/exploring-the-visualization-design-space-with-repertory-grids.png", "video": "https://www.youtube.com/watch?v=xfeBU3wvUyA"},
    {"id": 39, "year": 2018, "cat": "conf", "title": "EyeMSA: Exploring Eye Movement Data with Pairwise and Multiple Sequence Alignment", "authors": ["Burch, M.", "Kurzhals, K.", "Kleinhans, N.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "52:1–5", "doi": "10.1145/3204493.3204565", "detail": "Eye movement data can be regarded as a set of scan paths, each corresponding to one of the visual scanning strategies of a certain study participant. Finding common subsequences in those scan paths is a challenging task since they are typically not equally temporally long, do not consist of the same number of fixations, or do not lead along similar stimulus regions. In this paper we describe a technique based on pairwise and multiple sequence alignment to support a data analyst to see the most important patterns in the data. To reach this goal the scan paths are first transformed into a sequence of characters based on metrics as well as spatial and temporal aggregations. The result of the algorithmic data transformation is used as input for an interactive consensus matrix visualization. We illustrate the usefulness of the concepts by applying it to formerly recorded eye movement data investigating route finding tasks in public transport maps.", "image": "img/eyemsa-exploring-eye-movement-data-with-pairwise-and-multiple-sequence-alignment.png"},
    {"id": 40, "year": 2018, "cat": "conf", "title": "Image-Based Scanpath Comparison with Slit-Scan Visualization", "authors": ["Koch, M.", "Kurzhals, K.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "55:1–5", "doi": "10.1145/3204493.3204581", "detail": "The comparison of scanpaths between multiple participants is an important analysis task in eye tracking research. Established methods typically inspect recorded gaze sequences based on geometrical trajectory properties or strings derived from annotated areas of interest (AOIs). We propose a new approach based on image similarities of gaze-guided slit-scans: For each time step, a vertical slice is extracted from the stimulus at the gaze position. Placing the slices next to each other over time creates a compact representation of a scanpath in the context of the stimulus. These visual representations can be compared based on their image similarity, providing a new measure for scanpath comparison without the need for annotation. We demonstrate how comparative slit-scan visualization can be integrated into a visual analytics approach to support the interpretation of scanpath similarities in general.", "image": "img/image-based-scanpath-comparison-with-slit-scan-visualization.png", "video": "https://www.youtube.com/watch?v=CkFXeOUK4_0"},
    {"id": 41, "year": 2018, "cat": "thesis", "title": "Visual Analytics of Eye-Tracking and Video Data", "authors": ["Kurzhals, K."], "venue": "Dissertation, University of Stuttgart", "pages": "", "doi": "10.18419/OPUS-10299", "detail": "Eye tracking, i.e., the detection of gaze points, becomes increasingly popular in numerous research areas as a means to investigate perceptual and cognitive processes. In comparison to other evaluation methods, eye tracking provides insights into the distribution of attention and sequential viewing behavior, which are essential for many research questions. For visualization research, such insights help assess a visualization design and identify potential flaws. Gaze data coupled with a visual stimulus poses a complex analysis problem that is approached by statistical and visual methods. Statistical methods are often limited to hypothesis-driven evaluation and modeling of processes. Visualization is applied to confirm statistical results and for exploratory data analysis to form new hypotheses. Surveying the state of the art of visualizations for eye tracking shows a deficiency of appropriate methods, particularly for dynamic stimuli (e.g., videos). Video visualization and visual analytics provide methods that can be adapted to perform the required analysis processes. The automatic processing of video and gaze data is combined with interactive visualizations to provide an overview of the data, support efficient browsing, detect interesting events, and annotate important parts of the data. The techniques developed for this thesis focus on the analysis of videos from remote and from mobile eye tracking. The discussed remote eye-tracking scenarios consist of one video that is investigated by multiple participants. Mobile eye tracking comprises scenarios in which participants wear glasses with a built-in device to record their gaze. Both types of scenarios pose individual challenges that have to be addressed for an effective analysis. In general, the comparison of gaze behavior between participants plays an important role to detect common behavior and outliers. This thesis addresses the topic of eye tracking and visualization bidirectionally: Eye tracking is applied in user studies to evaluate visualization techniques beyond established performance measures and questionnaires. The current application of eye tracking in visualization research is surveyed. Further, it is discussed how existing methodology can be extended to incorporate eye tracking for future analysis scenarios. Vice versa, a set of new visualization techniques for data from remote and mobile eye-tracking devices are introduced that support the analysis of gaze behavior in general. Here, techniques for raw data and for data with annotations are introduced, as well as approaches to perform the tedious annotation process more efficiently.", "image": "img/visual-analytics-of-eye-tracking-and-video-data.png", "url": "https://elpub.uni-stuttgart.de/frontdoor/index/index/docId/10299"},
    {"id": 42, "year": 2017, "cat": "journal", "title": "Visualization of Eye Tracking Data: A Taxonomy and Survey", "authors": ["Blascheck, T.", "Kurzhals, K.", "Raschke, M.", "Burch, M.", "Weiskopf, D.", "Ertl, T."], "venue": "Computer Graphics Forum 36.8", "pages": "260–284", "doi": "10.1111/cgf.13079", "detail": "This survey provides an introduction into eye tracking visualization with an overview of existing techniques. Eye tracking is important for evaluating user behaviour. Analysing eye tracking data is typically done quantitatively, applying statistical methods. However, in recent years, researchers have been increasingly using qualitative and exploratory analysis methods based on visualization techniques. For this state‐of‐the‐art report, we investigated about 110 research papers presenting visualization techniques for eye tracking data. We classified these visualization techniques and identified two main categories: point‐based methods and methods based on areas of interest. Additionally, we conducted an expert review asking leading eye tracking experts how they apply visualization techniques in their analysis of eye tracking data. Based on the experts' feedback, we identified challenges that have to be tackled in the future so that visualizations will become even more widely applied in eye tracking research.", "image": "img/visualization-of-eye-tracking-data-a-taxonomy-and-survey.png"},
    {"id": 43, "year": 2017, "cat": "journal", "title": "Visual Analytics for Mobile Eye Tracking", "authors": ["Kurzhals, K.", "Hlawatsch, M.", "Seeger, C.", "Weiskopf, D."], "venue": "IEEE Transactions on Visualization and Computer Graphics 23.1", "pages": "301–310", "doi": "10.1109/tvcg.2016.2598695", "detail": "The analysis of eye tracking data often requires the annotation of areas of interest (AOIs) to derive semantic interpretations of human viewing behavior during experiments. This annotation is typically the most time-consuming step of the analysis process. Especially for data from wearable eye tracking glasses, every independently recorded video has to be annotated individually and corresponding AOIs between videos have to be identified. We provide a novel visual analytics approach to ease this annotation process by image-based, automatic clustering of eye tracking data integrated in an interactive labeling and analysis system. The annotation and analysis are tightly coupled by multiple linked views that allow for a direct interpretation of the labeled data in the context of the recorded video stimuli. The components of our analytics environment were developed with a user-centered design approach in close cooperation with an eye tracking expert. We demonstrate our approach with eye tracking data from a real experiment and compare it to an analysis of the data by manual annotation of dynamic AOIs. Furthermore, we conducted an expert user study with 6 external eye tracking researchers to collect feedback and identify analysis strategies they used while working with our application.", "image": "img/visual-analytics-for-mobile-eye-tracking.png", "video": "https://www.youtube.com/watch?v=0OPrTp8ybpk"},
    {"id": 44, "year": 2017, "cat": "chapter", "title": "A Task-Based View on the Visual Analysis of Eye-Tracking Data", "authors": ["Kurzhals, K.", "Burch, M.", "Blascheck, T.", "Andrienko, G.", "Andrienko, N.", "Weiskopf, D."], "venue": "in: Eye Tracking and Visualization (ETVIS) (Eds. Burch, Chuang, Fisher, Schmidt, Weiskopf), Springer, Cham", "pages": "3–22", "doi": "10.1007/978-3-319-47024-5_1", "detail": "The visual analysis of eye movement data has become an emerging field of research leading to many new visualization techniques in recent years. These techniques provide insight beyond what is facilitated by traditional attention maps and gaze plots, providing important means to support statistical analysis and hypothesis building. There is no single “all-in-one” visualization to solve all possible analysis tasks. In fact, the appropriate choice of a visualization technique depends on the type of data and analysis task. We provide a taxonomy of analysis tasks that is derived from literature research of visualization techniques and embedded in our pipeline model of eye-tracking visualization. Our task taxonomy is linked to references to representative visualization techniques and, therefore, it is a basis for choosing appropriate methods of visual analysis. We also elaborate on how far statistical analysis with eye-tracking metrics can be enriched by suitable visualization and visual analytics techniques to improve the extraction of knowledge during the analysis process.", "image": "img/a-task-based-view-on-the-visual-analysis-of-eye-tracking-data.png"},
    {"id": 45, "year": 2017, "cat": "conf", "title": "A Visual Analytics Approach for Semantic Multi-Video Annotation", "authors": ["John, M.", "Kurzhals, K.", "Koch, S.", "Weiskopf, D."], "venue": "2nd Workshop on Visualization for the Digital Humanities", "pages": "1–5", "doi": "", "detail": "The annotation of video material plays an important role in many Digital Humanities research fields including arts, political sciences, and cultural and historical studies. The annotations are typically assigned manually and convey rich semantics in accordance with the respective research question. In this work, we present the concept of a visual analytics approach that enables researchers to annotate multiple video sources in parallel. It combines methods from the fields of natural language processing and computer vision to support the manual annotation process with automatically extracted lowlevel characteristics. The benefits of our approach are twofold. With the extracted annotations and their visual mapping onto a suitable overview visualization, we support scholars in finding the relevant sections for their high-level annotations on the one hand, and on the other hand, we offer an environment that lets them compare and analyze such annotations in several videos at once. Our concept can be flexibly extended with additional processing methods to simplify annotation tasks further.", "image": "img/a-visual-analytics-approach-for-semantic-multi-video-annotation.png"},
    {"id": 46, "year": 2017, "cat": "conf", "title": "Close to the Action: Eye-Tracking Evaluation of Speaker-Following Subtitles", "authors": ["Kurzhals, K.", "Cetinkaya, E.", "Hu, Y.", "Wang, W.", "Weiskopf, D."], "venue": "CHI Conference on Human Factors in Computing Systems", "pages": "6559–6568", "doi": "10.1145/3025453.3025772", "detail": "The incorporation of subtitles in multimedia content plays an important role in communicating spoken content. For example, subtitles in the respective language are often preferred to expensive audio translation of foreign movies. The traditional representation of subtitles displays text centered at the bottom of the screen. This layout can lead to large distances between text and relevant image content, causing eye strain and even that we miss visual content. As a recent alternative, the technique of speaker-following subtitles places subtitle text in speech bubbles close to the current speaker. We conducted a controlled eye-tracking laboratory study (n = 40) to compare the regular approach (center-bottom subtitles) with content-sensitive, speaker-following subtitles. We compared different dialog-heavy video clips with the two layouts. Our results show that speaker-following subtitles lead to higher fixation counts on relevant image regions and reduce saccade length, which is an important factor for eye strain.", "image": "img/close-to-the-action-eye-tracking-evaluation-of-speaker-following-subtitles.png", "video": "https://www.youtube.com/watch?v=I3yYoIwJBGQ"},
    {"id": 47, "year": 2017, "cat": "conf", "title": "Flowbrush: Optical Flow Art", "authors": ["Kurzhals, K.", "Stoll, M.", "Bruhn, A.", "Weiskopf, D."], "venue": "Symposium on Computational Aesthetics in Graphics, Visualization, and Interactive Technology (SCA)", "pages": "1:1–9", "doi": "10.1145/3092912.3092914", "detail": "The depiction of motion in static representations has a long tradition in art and science alike. Often, motion is depicted by spatio-temporal summarizations that try to preserve as much information of the original dynamic content as possible. In our approach to depicting motion, we remove the spatial constraints and generate new content steered by the temporal changes in motion. Applying particle steering in combination with the dynamic color palette of the video content, we can create a wide range of different image styles. With recorded videos, or by live interaction with a webcam, one can influence the resulting image. We provide a set of intuitive parameters to affect the style of the result, the final image content depends on the video input. Based on a collection of results gathered from test users, we discuss example styles that can be achieved with FlowBrush. In general, our approach provides an open sandbox for creative people to generate aesthetic images from any video content they apply.", "image": "img/flowbrush-optical-flow-art.png"},
    {"id": 48, "year": 2016, "cat": "journal", "title": "VA2: A Visual Analytics Approach for Evaluating Visual Analytics Applications", "authors": ["Blascheck, T.", "John, M.", "Kurzhals, K.", "Koch, S.", "Ertl, T."], "venue": "IEEE Transactions on Visualization and Computer Graphics 22.1", "pages": "61–70", "doi": "10.1109/tvcg.2015.2467871", "detail": "Evaluation has become a fundamental part of visualization research and researchers have employed many approaches from the field of human-computer interaction like measures of task performance, thinking aloud protocols, and analysis of interaction logs. Recently, eye tracking has also become popular to analyze visual strategies of users in this context. This has added another modality and more data, which requires special visualization techniques to analyze this data. However, only few approaches exist that aim at an integrated analysis of multiple concurrent evaluation procedures. The variety, complexity, and sheer amount of such coupled multi-source data streams require a visual analytics approach. Our approach provides a highly interactive visualization environment to display and analyze thinking aloud, interaction, and eye movement data in close relation. Automatic pattern finding algorithms allow an efficient exploratory search and support the reasoning process to derive common eye-interaction-thinking patterns between participants. In addition, our tool equips researchers with mechanisms for searching and verifying expected usage patterns. We apply our approach to a user study involving a visual analytics application and we discuss insights gained from this joint analysis. We anticipate our approach to be applicable to other combinations of evaluation techniques and a broad class of visualization applications.", "image": "img/va2-a-visual-analytics-approach-for-evaluating-visual-analytics-applications.png"},
    {"id": 49, "year": 2016, "cat": "journal", "title": "Eye Tracking Evaluation of Visual Analytics", "authors": ["Kurzhals, K.", "Fisher, B.", "Burch, M.", "Weiskopf, D."], "venue": "Information Visualization 15.4", "pages": "340–358", "doi": "10.1177/1473871615609787", "detail": "The application of eye tracking for the evaluation of humans’ viewing behavior is a common approach in psychological research. So far, the use of this technique for the evaluation of visual analytics and visualization is less prominent. We investigate recent scientific publications from the main visualization and visual analytics conferences and journals, as well as related research fields that include an evaluation by eye tracking. Furthermore, we provide an overview of evaluation goals that can be achieved by eye tracking and state-of-the-art analysis techniques for eye tracking data. Ideally, visual analytics leads to a mixed-initiative cognitive system where the mechanism of distribution is the interaction of the user with the visualization environment. Therefore, we also include a discussion of cognitive approaches and models to include the user in the evaluation process. Based on our review of the current use of eye tracking evaluation in our field and the cognitive theory, we propose directions for future research on evaluation methodology, leading to the grand challenge of developing an evaluation approach to the mixed-initiative cognitive system of visual analytics.", "image": "img/eye-tracking-evaluation-of-visual-analytics.png"},
    {"id": 50, "image": "img/gaze stripes.png", "year": 2016, "cat": "journal", "title": "GazeStripes: Image-Based Visualization of Eye Tracking Data", "authors": ["Kurzhals, K.", "Hlawatsch, M.", "Heimerl, F.", "Burch, M.", "Ertl, T.", "Weiskopf, D."], "venue": "IEEE Transactions on Visualization and Computer Graphics 22.1", "pages": "1005–1014", "doi": "10.1109/tvcg.2015.2468091", "detail": "We present a new visualization approach for displaying eye tracking data from multiple participants. We aim to show the spatio-temporal data of the gaze points in the context of the underlying image or video stimulus without occlusion. Our technique, denoted as gaze stripes, does not require the explicit definition of areas of interest but directly uses the image data around the gaze points, similar to thumbnails for images. A gaze stripe consists of a sequence of such gaze point images, oriented along a horizontal timeline. By displaying multiple aligned gaze stripes, it is possible to analyze and compare the viewing behavior of the participants over time. Since the analysis is carried out directly on the image data, expensive post-processing or manual annotation are not required. Therefore, not only patterns and outliers in the participants' scanpaths can be detected, but the context of the stimulus is available as well. Furthermore, our approach is especially well suited for dynamic stimuli due to the non-aggregated temporal mapping. Complementary views, i.e., markers, notes, screenshots, histograms, and results from automatic clustering, can be added to the visualization to display analysis results. We illustrate the usefulness of our technique on static and dynamic stimuli. Furthermore, we discuss the limitations and scalability of our approach in comparison to established visualization techniques.", "video": "https://www.youtube.com/watch?v=ynlqqbVNZCY"},
    {"id": 51, "year": 2016, "cat": "journal", "title": "Visual Movie Analytics", "authors": ["Kurzhals, K.", "John, M.", "Heimerl, F.", "Kuznecov, P.", "Weiskopf, D."], "venue": "IEEE Transactions on Multimedia 18.11", "pages": "2149–2160", "doi": "10.1109/tmm.2016.2614184", "detail": "The analysis of inherent structures of movies plays an important role in studying stylistic devices and specific, content-related questions. Examples are the analysis of personal constellations in movie scenes, dialogue-based content analysis, or the investigation of image-based features. We provide a visual analytics approach that supports the analytical reasoning process to derive higher level insights about the content on a semantic level. Combining automatic methods for semantic scene analysis based on script and subtitle text, we perform a low-level analysis of the data automatically. Our approach features an interactive visualization that allows a multilayer interpretation of descriptive features to characterize movie content. For semantic analysis, we extract scene information from movie scripts and match them with the corresponding subtitles. With text- and image-based query techniques, we facilitate an interactive comparison of different movie scenes on an image and on a semantic level. We demonstrate how our approach can be applied for content analysis on a popular Hollywood movie.", "image": "img/visual-movie-analytics.png"},
    {"id": 52, "year": 2016, "cat": "journal", "title": "User Performance and Reading Strategies for Metro Maps: An Eye Tracking Study", "authors": ["Netzel, R.", "Ohlhausen, B.", "Kurzhals, K.", "Woods, R.", "Burch, M.", "Weiskopf, D."], "venue": "Spatial Cognition & Computation 17.1–2", "pages": "39–64", "doi": "10.1080/13875868.2016.1226839", "detail": "We conducted a controlled empirical eye tracking study with 40 participants using schematic metro maps. The study focused on two aspects: determining different reading strategies and assessing user performance. We considered the following factors: color encoding (color vs. gray-scale), map complexity (three levels), and task difficulty (three levels). There was one type of task: find a route from a start to a target location and state the number of transfers that have to be performed. To identify reading strategies, we annotated fixations of scanpaths, computed a transition matrix of each annotated scanpath, and used these matrices as input to cluster scanpaths into groups of similar behavior. We show how these reading strategies relate to the geodesic structure of the scanpaths' fixations projected onto the geodesic line that connects start and target locations. The analysis of the eye tracking data is complemented by statistical inference working on two eye tracking metrics (average fixation duration and saccade length). User performance was evaluated with a statistical analysis of task correctness and completion time. Our study shows that the design factors have a significant impact on user task performance. Also, we were able to identify typical reading strategies like directly finding a path from start to target location. Often, participants check the correctness of their result multiple times by moving back and forth between start and target. Our findings also indicate that the choice of reading strategies does not depend on whether color or gray-scale encoding is used.", "image": "img/user-performance-and-reading-strategies-for-metro-maps-an-eye-tracking-study.png"},
    {"id": 53, "year": 2016, "cat": "conf", "title": "AOI Hierarchies for Visual Exploration of Fixation Sequences", "authors": ["Blascheck, T.", "Kurzhals, K.", "Raschke, M.", "Strohmaier, S.", "Weiskopf, D.", "Ertl, T."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "111–118", "doi": "10.1145/2857491.2857524", "detail": "In eye tracking studies a complex visual stimulus requires the definition of many areas of interest (AOIs). Often these AOIs have an inherent, nested hierarchical structure that can be utilized to facilitate analysis tasks. We discuss how this hierarchical AOI structure in combination with appropriate visualization techniques can be applied to analyze fixation sequences on differently aggregated levels. An AOI View, AOI Tree, AOI Matrix, and AOI Graph enable a bottom-up and top-down evaluation of fixation sequences. We conducted an expert review and compared our techniques to current state-of-the-art visualization techniques in eye movement research to further improve and extend our approach. To show how our approach is used in practice, we evaluate fixation sequences collected during a study where 101 AOIs are organized hierarchically.", "image": "img/aoi-hierarchies-for-visual-exploration-of-fixation-sequences.png"},
    {"id": 54, "year": 2016, "cat": "conf", "title": "Fixation-Image Charts", "authors": ["Kurzhals, K.", "Hlawatsch, M.", "Burch, M.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "11–18", "doi": "10.1145/2857491.2857507", "detail": "We facilitate the comparative visual analysis of eye tracking data from multiple participants with a visualization that represents the temporal changes of viewing behavior. Common approaches to visually analyze eye tracking data either occlude or ignore the underlying visual stimulus, impairing the interpretation of displayed measures. We introduce fixation-image charts: a new technique to display the temporal changes of fixations in the context of the stimulus without visual overlap between participants. Fixation durations, the distance and direction of saccades between consecutive fixations, as well as the stimulus context can be interpreted in one visual representation. Our technique is not limited to static stimuli, but can be applied to dynamic stimuli as well. Using fixation metrics and the visual similarity of stimulus regions, we complement our visualization technique with an interactive filter concept that allows for the identification of interesting fixation sequences without the time-consuming annotation of areas of interest. We demonstrate how our technique can be applied to different types of stimuli to perform a range of analysis tasks; and discuss advantages and shortcomings derived from a preliminary user study.", "image": "img/fixation-image-charts.png", "video": "https://www.youtube.com/watch?v=tMWpVs49jvo"},
    {"id": 55, "year": 2016, "cat": "conf", "title": "Visualizing Eye Tracking Data with Gaze-Guided Slit-Scans", "authors": ["Kurzhals, K.", "Weiskopf, D."], "venue": "IEEE Second Workshop on Eye Tracking and Visualization (ETVIS)", "pages": "45–49", "doi": "10.1109/etvis.2016.7851165", "detail": "The slit-scan technique is applied as a means to create artistic static and dynamic representations of motion in videos by arranging small slits of each video frame next to each other. This technique produces compact representations evenfor long timespansof recorded video material. We adapt this approach for the comparison of eye tracking data from multiple participants watching video. We adjust the slit position according to the current gaze coordinates of a participant and display the visual attention in context of the underlying stimulus over time. With additional encodings for the absolute horizontal and vertical position of a gaze point, we present a new visualization technique for scanpath representation.", "image": "img/visualizing-eye-tracking-data-with-gaze-guided-slit-scans.png"},
    {"id": 56, "year": 2015, "cat": "journal", "title": "Eye Tracking in Computer-Based Visualization", "authors": ["Kurzhals, K.", "Burch, M.", "Pfeiffer, T.", "Weiskopf, D."], "venue": "Computing in Science & Engineering 17.5", "pages": "64–71", "doi": "10.1109/mcse.2015.93", "detail": "ye tracking is popular in many fields, including marketing, psychology, and human-computer interaction. Advances in technology have led to lower prices for eye-tracking hardware and, consequently, a widespread availability of affordable devices. Accordingly, we’ve seen a trend toward a broader use of eye tracking in other areas as well.", "image": "img/eye-tracking-in-computer-based-visualization.jpg"},
    {"id": 57, "year": 2015, "cat": "journal", "title": "Eye Tracking for Personal Visual Analytics", "authors": ["Kurzhals, K.", "Weiskopf, D."], "venue": "IEEE Computer Graphics and Applications 35.4", "pages": "64–72", "doi": "10.1109/mcg.2015.47", "detail": "In many research fields, eye tracking has become an established method to analyze the distribution of visual attention in various scenarios. In the near future, eye tracking is expected to become ubiquitous, recording massive amounts of data in everyday situations. To make use of this data, new approaches for personal visual analytics will be necessary to make the data accessible, allowing nonexpert users to re-experience interesting events and benefit from self-reflection. This article discusses how eye tracking fits in the context of personal visual analytics, the challenges that arise with its application to everyday situations, and the research perspectives of personal eye tracking. As an example, the authors present a technique for representing areas of interest (AOIs) from multiple videos: the AOI cloud. They apply this technique to examine a user's personal encounters with other people.", "image": "img/eye-tracking-for-personal-visual-analytics.png", "video": "https://www.youtube.com/watch?v=lq0X-0t-ja8"},
    {"id": 58, "year": 2015, "cat": "journal", "title": "Visual Analytics for Video Applications", "authors": ["Tanisaro, P.", "Schöning, J.", "Kurzhals, K.", "Heidemann, G.", "Weiskopf, D."], "venue": "it – Information Technology 57.1", "pages": "30–36", "doi": "10.1515/itit-2014-1072", "detail": "In this article, we describe the concept of video visual analytics with a special focus on the reasoning process in the sensemaking loop. To illustrate this concept with real application scenarios, two visual analytics tools one for video surveillance and one for eye-tracking data analysis that cover the sensemaking process, are discussed in detail. Various aspects of video surveillance such as browsing and playback, situational awareness, and deduction of reasoning from visual analytics are examined. On account of the visual analysis of recorded eye tracking data from watching video, application features such as a space-time cube, spatio-temporal clustering, and automatic comparison of multiple participants are reviewed of how they can support the analytical process. Based on this knowledge, open challenges in video visual analytics are discussed in the conclusion.", "image": "img/visual-analytics-for-video-applications.png"},
    {"id": 59, "year": 2015, "cat": "conf", "title": "Visual Analysis of Visitor Behavior for Indoor Event Management", "authors": ["Krüger, R.", "Heimerl, F.", "Han, Q.", "Kurzhals, K.", "Koch, S.", "Ertl, T."], "venue": "48th Hawaii International Conference on System Sciences (HICSS)", "pages": "1148–1157", "doi": "10.1109/hicss.2015.139", "detail": "The analysis of persons' indoor movement and behavior patterns can be of great value. Such an analysis enables managers and organizers in understanding the needs of customers and visitors. Event planning for exhibitions, festivals, and conferences, but also optimization of malls and stores can benefit from recorded visitor data. To show the advantage of visual analysis of movement information, we apply a new visual approach to a large indoor dataset, recorded at the republican conference in 2013. We present three different interactive visualization methods to reveal patterns, to deduce behavior from participants' movements, and to show transitions between sessions and topics. For this, we apply a spectral hierarchical clustering approach and visualize results in a pixel based scarf plot. Additionally, we introduce a prediction model and visualization which serves as a monitoring tool for visitor attraction and distribution and helps to prevent bottleneck situations. We evaluate our approach by showing its applicability in a case study and validate our model on ground truth data.", "image": "img/visual-analysis-of-visitor-behavior-for-indoor-event-management.png"},
    {"id": 60, "year": 2015, "cat": "conf", "title": "AOI Transition Trees", "authors": ["Kurzhals, K.", "Weiskopf, D."], "venue": "41st Graphics Interface Conference (GI)", "pages": "41–48", "doi": "10.5555/2788890.2788899", "detail": "The analysis of transitions between areas of interest (AOIs) in eye tracking data provides insight into visual reading strategies followed by participants. We present a new approach to investigate eye tracking data of multiple participants, recorded from video stimuli. Our new transition trees summarize sequence patterns of all participants over complete videos. Shot boundary information from the video is used to divide the dynamic eye tracking information into time spans of similar semantics. AOI transitions within such a time span are modeled as a tree and visualized by an extended icicle plot that shows transition patterns and frequencies of transitions. Thumbnails represent AOIs in the visualization and allow for an interpretation of AOIs and transitions between them without detailed knowledge of the video stimulus. A sequence of several shots is visualized by connecting the respective icicle plots with curved links that indicate the correspondence of AOIs. We compare the technique with other approaches that visualize AOI transitions. With our approach, common transition patterns in eye tracking data recorded for several participants can be identified easily. In our use case, we demonstrate the scalability of our approach concerning the number of participants and investigate a video data set with the transition tree visualization.", "image": "img/aoi-transition-trees.png", "video": "https://www.youtube.com/watch?v=iI4HAoLQPiA"},
    {"id": 61, "year": 2014, "cat": "journal", "title": "Evaluation of Attention-Guiding Video Visualization", "authors": ["Kurzhals, K.", "Höferlin, M.", "Weiskopf, D."], "venue": "Computer Graphics Forum 32.3 (pt. 1)", "pages": "51–60", "doi": "10.1111/cgf.12092", "detail": "We investigate four different variants of attention‐guiding video visualization techniques that aim to help users distribute their attention equally among potential objects of interest: bounding box visualization, force‐directed visualization, top‐down visualization, grid visualization. Objects of interest are highlighted by rectangular shapes and then we concentrate on the manipulation of color, motion, and size. We conducted a controlled laboratory user study (n=25) to compare the four visualization techniques and the unmodified video material as baseline. We evaluated task performance and distribution of attention in a search task. These two properties become especially important when video material with numerous objects has to be observed. The distribution of attention was measured by eye tracking. Our results show that a more even distribution of attention between the objects can be achieved by attention‐guiding visualization, compared to unmodified video. Many participants feel more comfortable when they look at bounding boxes and the grid, but improvements in search task performance could not be confirmed.", "image": "img/evaluation-of-attention-guiding-video-visualization.png", "video": "https://www.youtube.com/watch?v=xEL8NnP0wdk"},
    {"id": 62, "year": 2014, "cat": "journal", "title": "Space-Time Visual Analytics of Eye-Tracking Data for Dynamic Stimuli", "authors": ["Kurzhals, K.", "Weiskopf, D."], "venue": "IEEE Transactions on Visualization and Computer Graphics 19.12", "pages": "2129–2138", "doi": "10.1109/tvcg.2013.194", "detail": "We introduce a visual analytics method to analyze eye movement data recorded for dynamic stimuli such as video or animated graphics. The focus lies on the analysis of data of several viewers to identify trends in the general viewing behavior, including time sequences of attentional synchrony and objects with strong attentional focus. By using a space-time cube visualization in combination with clustering, the dynamic stimuli and associated eye gazes can be analyzed in a static 3D representation. Shotbased, spatiotemporal clustering of the data generates potential areas of interest that can be filtered interactively. We also facilitate data drill-down: the gaze points are shown with density-based color mapping and individual scan paths as lines in the space-time cube. The analytical process is supported by multiple coordinated views that allow the user to focus on different aspects of spatial and temporal information in eye gaze data. Common eye-tracking visualization techniques are extended to incorporate the spatiotemporal characteristics of the data. For example, heat maps are extended to motion-compensated heat maps and trajectories of scan paths are included in the space-time visualization. Our visual analytics approach is assessed in a qualitative users study with expert users, which showed the usefulness of the approach and uncovered that the experts applied different analysis strategies supported by the system.", "image": "img/space-time-visual-analytics-of-eye-tracking-data-for-dynamic-stimuli.png", "video": "https://www.youtube.com/watch?v=dtM92w974I4"},
    {"id": 63, "year": 2014, "cat": "conf", "title": "State-of-the-Art of Visualization for Eye Tracking Data", "authors": ["Blascheck, T.", "Kurzhals, K.", "Raschke, M.", "Burch, M.", "Weiskopf, D.", "Ertl, T."], "venue": "EuroVis – STARs", "pages": "63–82", "doi": "10.2312/EUROVISSTAR.20141173", "detail": "Eye tracking technology is becoming easier and cheaper to use, resulting in its increasing application to numerous fields of research. The data collected during an eye tracking experiment can be analyzed by statistical methods and/or with visualization techniques. Visualizations can reveal characteristics of fixations, saccades, and scanpath structures. In this survey, we present an overview of visualization techniques for eye tracking data and describe their functionality. We classify the visualization techniques using nine categories. The categories are based on properties of eye tracking data, including aspects of the stimuli and the viewer, and on properties of the visualization techniques. The classification of about 90 publications including technical as well as application papers with modifications of common visualization techniques are described in more detail. We finally present possible directions for further research in the field of eye tracking data visualization.", "image": "img/state-of-the-art-of-visualization-for-eye-tracking-data.png"},
    {"id": 64, "year": 2014, "cat": "conf", "title": "Visual Task Solution Strategies in Public Transport Maps", "authors": ["Burch, M.", "Kurzhals, K.", "Weiskopf, D."], "venue": "ET4S @ GIScience", "pages": "32–36", "doi": "", "detail": "Public transport maps are used as visual aid for travellers to support the route finding task from a start to a destination. Although those maps are designed in a user-friendly manner by applying effective layouts, color codings, as well as intuitive symbolic representations it is unclear which perceptual, readability, and understandability problems the human user has when looking at those maps. In a preliminary eye tracking experiment with 8 participants, we asked people to find a way between highlighted start and destination stations on different maps. Based on a visual scanpath analysis, we discovered a set of different visual task solution strategies that will build the foundation for hypotheses to evaluate in a final user study.", "image": "img/visual-task-solution-strategies-in-public-transport-maps.png"},
    {"id": 65, "year": 2014, "cat": "conf", "title": "How Do People Read Metro Maps? An Eye Tracking Study", "authors": ["Burch, M.", "Raschke, M.", "Blascheck, T.", "Kurzhals, K.", "Weiskopf, D."], "venue": "1st International Workshop on Schematic Mapping (Schematics)", "pages": "", "doi": "", "detail": "Metro maps have many benefits over traditional geospatial maps. A common task to be solved when traveling in a foreign city is to find an economical and efficient way from the start to the destination point. When metro maps become larger containing several different lines and a large number of stations with possible change points, this task gets more complicated. In this paper, we present the results of an eye tracking experiment with the goal to investigate difficulties that people have when reading such maps. To this end, we showed participants several real-world metro maps and asked them to perform tasks of different complexity, ie routes with and without highlighted start and destination stations. The major result of this study is that the number of stations, lines, and highlights have an impact on task completion times and on visual task solution strategies.", "image": "img/how-do-people-read-metro-maps-an-eye-tracking-study.png"},
    {"id": 66, "year": 2014, "cat": "conf", "title": "Benchmark Data for Evaluating Visualization and Analysis Techniques for Eye Tracking for Video Stimuli", "authors": ["Kurzhals, K.", "Bopp, C. F.", "Bässler, J.", "Ebinger, F.", "Weiskopf, D."], "venue": "Fifth Workshop on Beyond Time and Errors: Novel Evaluation Methods for Visualization", "pages": "54–60", "doi": "10.1145/2669557.2669558", "detail": "For the analysis of eye movement data, an increasing number of analysis methods have emerged to examine and analyze different aspects of the data. In particular, due to the complex spatio-temporal nature of gaze data for dynamic stimuli, there has been a need and recent trend toward the development of visualization and visual analytics techniques for such data. With this paper, we provide benchmark data to test visualization and visual analytics methods, but also other analysis techniques for gaze processing. In particular, for eye tracking data from video stimuli, existing datasets often provide few information about recorded eye movement patterns and, therefore, are not comprehensive enough to allow for a faithful assessment of the analysis methods. Our benchmark data consists of three ingredients: the dynamic stimuli in the form of video, the eye tracking data, and annotated areas of interest. We designed the video stimuli and the tasks for the participants of the eye tracking experiments in a way to trigger typical viewing patterns, including attentional synchrony, smooth pursuit, and switching of the focus of attention. In total, we created 11 videos with eye tracking data acquired from 25 participants.", "image": "img/benchmark-data-for-evaluating-visualization-and-analysis-techniques-for-eye-tracking-for-video-stimuli.png"},
    {"id": 67, "year": 2014, "cat": "conf", "title": "Evaluating Visual Analytics with Eye Tracking", "authors": ["Kurzhals, K.", "Fisher, B.", "Burch, M.", "Weiskopf, D."], "venue": "Fifth Workshop on Beyond Time and Errors: Novel Evaluation Methods for Visualization", "pages": "61–69", "doi": "10.1145/2669557.2669560", "detail": "The application of eye tracking for the evaluation of humans' viewing behavior is a common approach in psychological research. So far, the use of this technique for the evaluation of visual analytics and visualization is less prominent. We investigate recent scientific publications from the main visualization and visual analytics conferences and journals that include an evaluation by eye tracking. Furthermore, we provide an overview of evaluation goals that can be achieved by eye tracking and state-of-the-art analysis techniques for eye tracking data. Ideally, visual analytics leads to a mixed-initiative cognitive system where the mechanism of distribution is the interaction of the user with visualization environments. Therefore, we also include a discussion of cognitive approaches and models to include the user in the evaluation process. Based on our review of the current use of eye tracking evaluation in our field and the cognitive theory, we propose directions of future research on evaluation methodology, leading to the grand challenge of developing an evaluation approach to the mixed-initiative cognitive system of visual analytics.", "image": "img/evaluating-visual-analytics-with-eye-tracking.png"},
    {"id": 68, "year": 2014, "cat": "conf", "title": "ISeeCube: Visual Analysis of Gaze Data for Video", "authors": ["Kurzhals, K.", "Heimerl, F.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "43–50", "doi": "10.1145/2578153.2578158", "detail": "We introduce a new design for the visual analysis of eye tracking data recorded from dynamic stimuli such as video. ISeeCube includes multiple coordinated views to support different aspects of various analysis tasks. It combines methods for the spatiotemporal analysis of gaze data recorded from unlabeled videos as well as the possibility to annotate and investigate dynamic Areas of Interest (AOIs). A static overview of the complete data set is provided by a space-time cube visualization that shows gaze points with densitybased color mapping and spatiotemporal clustering of the data. A timeline visualization supports the analysis of dynamic AOIs and the viewers' attention on them. Individual and similar viewing patterns of different viewers can be clustered by their Levenshtein distance, an attention map, or the transitions between AOIs. With the provided visual analytics techniques, the exploration of eye tracking data recorded from several viewers is supported for a wide range of various analysis tasks.", "image": "img/iseecube-visual-analysis-of-gaze-data-for-video.png", "video": "https://www.youtube.com/watch?v=41cTIApjmdw"},
    {"id": 69, "year": 2013, "cat": "journal", "title": "Evaluation of Fast-Forward Video Visualization", "authors": ["Höferlin, M.", "Kurzhals, K.", "Hoferlin, B.", "Heidemann, G.", "Weiskopf, D."], "venue": "IEEE Transactions on Visualization and Computer Graphics 18.12", "pages": "2095–2103", "doi": "10.1109/tvcg.2012.222", "detail": "We evaluate and compare video visualization techniques based on fast-forward. A controlled laboratory user study (n = 24) was conducted to determine the trade-off between support of object identification and motion perception, two properties that have to be considered when choosing a particular fast-forward visualization. We compare four different visualizations: two representing the state-of-the-art and two new variants of visualization introduced in this paper. The two state-of-the-art methods we consider are frame-skipping and temporal blending of successive frames. Our object trail visualization leverages a combination of frame-skipping and temporal blending, whereas predictive trajectory visualization supports motion perception by augmenting the video frames with an arrow that indicates the future object trajectory. Our hypothesis was that each of the state-of-the-art methods satisfies just one of the goals: support of object identification or motion perception. Thus, they represent both ends of the visualization design. The key findings of the evaluation are that object trail visualization supports object identification, whereas predictive trajectory visualization is most useful for motion perception. However, frame-skipping surprisingly exhibits reasonable performance for both tasks. Furthermore, we evaluate the subjective performance of three different playback speed visualizations for adaptive fast-forward, a subdomain of video fast-forward.", "image": "img/evaluation-of-fast-forward-video-visualization.png", "video": "https://www.youtube.com/watch?v=1iJPxTP2yVs"},
    {"id": 70, "image": "img/The Challenges of Eye-Tracking Visualization in Multi-User Collaboration.png", "year": 2026, "cat": "conf", "title": "The Challenges of Eye-Tracking Visualization in Multi-User Collaboration", "authors": ["Kurzhals, K.", "Koch, M.", "Pathmanathan, N.", "Rau, T.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–6", "doi": "10.1145/3797246.3805719", "detail": "This work discusses the application of eye tracking and visualization in collaborative scenarios involving two or more people. Based on our recent prior work on co-located scenarios, where all participants are in one room, we discuss the challenges and outline future research directions, also including remote collaboration. This work showcases different scenarios of our previous research and reflects on aspects for future applications. We categorize the discussed examples into different dimensions: post-experiment analysis, live gaze communication, and eye tracking with head-mounted displays or glasses. Two examples comprise eye tracking for evaluation purposes for augmented reality and creative workshop analysis with multimodal data recordings. In both cases, eye tracking can provide valuable insights into human visual perception and cognitive processes during collaborative tasks."},
    {"id": 71, "image": "img/eyes-in-the-clouds.png", "year": 2026, "cat": "journal", "title": "Eyes in the Clouds: Spatial Data Analysis with Gaze-Enhanced Point Clouds", "authors": ["Geringer, S.", "Balangé, L.", "Becher, M.", "Pathmanathan, N.", "Kerekes, G.", "Schwieger, V.", "Weiskopf, D.", "Kurzhals, K."], "venue": "Journal of Visualization 29.3", "pages": "547–563", "doi": "10.1007/s12650-025-01096-z", "detail": "Spatial data analysis is essential in domains such as construction, architecture, and geodesy, to check for differences between construction stages of a building. In this context, real-world environments are often digitally recorded as point clouds, providing a basis for digital processing and analysis. Furthermore, aspects of spatial cognition, often measured with eye tracking, are also relevant to many research questions related to how people perceive and understand space and spatial structures, e.g., in quality inspection of construction sites or buildings. We present a workflow to combine eye tracking and point cloud data to analyze user attention during inspection of spatial data in virtual environments. This type of data enrichment enables the deployment of established open-source software for cloud and mesh processing to analyze eye tracking data. Our workflow employs the investigation of point cloud data and simultaneous user gaze recording in virtual reality, followed by point-based gaze data analysis, interactive visualization, and authoring and production of high-quality dissemination materials for stakeholders. We showcase our approach with a usage scenario on how people investigate the construction of a pavilion building in virtual reality."},
    {"id": 72, "image": "img/Immersive Analysis of Multifield Point Clouds.png", "year": 2025, "cat": "conf", "title": "Immersive Analysis of Multifield Point Clouds", "authors": ["Flach, A.", "Rau, T.", "Becher, M.", "Sedlmair, M.", "Kurzhals, K."], "venue": "18th International Symposium on Visual Information Communication and Interaction (VINCI)", "pages": "1–8", "doi": "10.1145/3769534.3769566", "detail": "Point clouds are used to measure and assess building processes in areas such as architecture, engineering, and construction. Precise spatial measurements can inform about deviations from a baseline, and the increasing use of sensor data in the context of building information modeling leads to multiple scalar fields containing rich information of individual spatial points. We propose an immersive approach to investigate such multivariate point cloud data from scans of buildings. We compare a switching approach that provides an overview of individual scalar fields with a spotlight that provides local information about all fields simultaneously. Furthermore, locomotion is compared for such immersive analysis with teleportation and with an omnidirectional treadmill. Our results show a preference for free movement and a task-dependence of visualization approaches for the inspection of scalar fields."},
    {"id": 73, "image": "img/Eye Tracking Studies in Visualization- Phases, Guidelines, and Checklist.png", "year": 2025, "cat": "conf", "title": "Eye Tracking Studies in Visualization: Phases, Guidelines, and Checklist", "authors": ["Burch, M.", "Kurzhals, K.", "Weiskopf, D."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–7", "doi": "10.1145/3715669.3725877", "detail": "Qualitative and quantitative eye tracking studies are prominent in many fields to understand behavior related to visual attention, in particular, for visualization research. The design, setup, and execution of a study, as well as the analysis of the acquired eye tracking data, can be difficult. This work proposes guidelines for eye tracking studies in visualization. We differentiate three major phases, focusing on before, during, and after a study. These guidelines are based on our experiences from conducting more than 100 eye tracking studies and additional literature research for each phase. As a result, we present a structured plan and chronological order of general requirements as a checklist for conducting eye tracking studies. A living document of the checklist can be found at: https://github.com/mibu1976/etvis2025"},
    {"id": 74, "image": "img/Uncertainty-Aware Scarf Plots.png", "year": 2025, "cat": "conf", "title": "Uncertainty-Aware Scarf Plots", "authors": ["Pathmanathan, N.", "Öney, S.", "Koch, M.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–8", "doi": "10.1145/3715669.3725872", "detail": "Multiple challenges emerge when analyzing eye-tracking data with areas of interest (AOIs) because recordings are subject to different sources of uncertainties. Previous work often presents gaze data without considering those inaccuracies in the data. To address this issue, we developed uncertainty-aware scarf plot visualizations that aim to make analysts aware of uncertainties with respect to the position-based mapping of gaze to AOIs and depth dependency in 3D scenes. Additionally, we also consider uncertainties in automatic AOI annotation. We showcase our approach in comparison to standard scarf plots in an augmented reality scenario."},
    {"id": 75, "image": "img/Group Gaze-Sharing with Projection Displays.png", "year": 2025, "cat": "conf", "title": "Group Gaze-Sharing with Projection Displays", "authors": ["Koch, M.", "Rau, T.", "Mikheev, V.", "Öney, S.", "Becher, M.", "Wang, X.", "Pathmanathan, N.", "Gralka, P.", "Weiskopf, D.", "Kurzhals, K."], "venue": "ACM Symposium on Eye Tracking Research and Applications (ETRA)", "pages": "1–7", "doi": "10.1145/3715669.3725871", "detail": "The eyes play an important role in human collaboration. Mutual and shared gaze help communicate visual attention to each other or to a specific object of interest. Shared gaze was typically investigated for pair collaborations in remote settings and with people in virtual and augmented reality. With our work, we expand this line of research by a new technique to communicate gaze between groups in tabletop workshop scenarios. To achieve this communication, we use an approach based on projection mapping to unify gaze data from multiple participants into a common visualization space on a tabletop. We showcase our approach with a collaborative puzzle-solving task that displays shared visual attention on individual pieces and provides hints to solve the problem at hand."},
    {"id": 76, "image": "img/The Joy of Co-Painting- Creative Human-AI Collaboration.png", "year": 2025, "cat": "conf", "title": "The Joy of Co-Painting: Creative Human-AI Collaboration for Traceable Image-Generation Workflows", "authors": ["Satkunarajan, J.", "Koch, S.", "Kurzhals, K."], "venue": "IEEE Pacific Visualization Conference (PacificVis)", "pages": "318–328", "doi": "10.1109/pacificvis64226.2025.00038", "detail": "Image-generative models have gained popularity over the last years with their ability to create realistic artwork. Realizing complex artworks with specific creative ideas often requires iterative optimization of specialized prompts, but may still result in inadequate images. The inclusion of reference images and adapting modelspecific parameters can help in steering the model and fostering the creative intent of the user. But by providing text prompts, initial images, and adapting model parameters, users face a vast design space for creating images. To navigate through this space, we propose a visualization approach that combines an interactive Provenance Graph, parameter visualizations, and high-dimensional embeddings. Our approach helps pursue multiple parallel creation paths, makes workflows traceable and parameter changes transparent, and facilitates the reporting of image editing steps. In addition to prompt formulation, we focus on targeted generation by probing parameters, image compositions, and editing details. We integrate the generative process into existing image editing software, enabling users to compose artwork in collaboration with the model. The presented approach is evaluated in a user experiment ($\\mathrm{n}=9$) for generating artwork. The results show that users with different levels of experience can create targeted artwork but use different strategies when working with the Provenance Graph."}
  ]
};
